begin;
select no_plan();
select has_function('public','start_media_cleanup_run',array[]::text[],'exclusive cleanup run exists');
select has_function('public','finish_media_cleanup_run',array['uuid','boolean'],'cleanup run completion exists');
select has_function('public','claim_media_cleanup',array['integer'],'service-only cleanup claim exists');
select has_function('public','claim_retired_article_prefixes',array['integer'],'service-only prefix claim exists');
select ok(not has_function_privilege('authenticated','public.claim_media_cleanup(integer)','EXECUTE'),'authenticated users cannot claim storage keys');
select ok(not has_function_privilege('anon','public.claim_retired_article_prefixes(integer)','EXECUTE'),'anonymous users cannot claim prefixes');
insert into private.article_id_registry(article_id) values('86000000-0000-4000-8000-000000000001');
insert into private.retired_article_ids(article_id) values('86000000-0000-4000-8000-000000000001');
insert into private.media_key_registry(object_key,asset_id,article_id,retired) values('synthetic-ledger-key','86000000-0000-4000-8000-000000000002','86000000-0000-4000-8000-000000000001',true);
insert into private.media_cleanup_ledger(object_key,asset_id,article_id) values('synthetic-ledger-key','86000000-0000-4000-8000-000000000002','86000000-0000-4000-8000-000000000001');
set local role service_role;
select set_config('test.run_token',public.start_media_cleanup_run()::text,true);
select isnt(current_setting('test.run_token'),'','cleanup run starts');
select is(public.start_media_cleanup_run(),null::uuid,'overlapping cleanup run is rejected');
select is(public.finish_media_cleanup_run('86000000-0000-4000-8000-000000000099',true),false,'wrong run token cannot mark healthy');
select is(public.finish_media_cleanup_run(current_setting('test.run_token')::uuid,true),true,'successful run records readiness');
select set_config('test.run_token',public.start_media_cleanup_run()::text,true);
select is(public.finish_media_cleanup_run(current_setting('test.run_token')::uuid,false),true,'failed run is recorded');
reset role;
select is((select last_healthy_at from private.media_cleanup_runtime where id=true),null,'failed run invalidates previous readiness');
update auth.users set email='cleanup-admin@bc.edu',email_confirmed_at=now(),raw_app_meta_data='{"provider":"google"}'::jsonb where id='00000000-0000-0000-0000-000000000004';
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000004',true);
select is(public.delete_archived_article('86000000-0000-4000-8000-000000000099',1,'86000000-0000-4000-8000-000000000098',true)->>'code','cleanup_unavailable','failed cleanup blocks further deletion');
reset role;
set local role service_role;
select set_config('test.cleanup_token',(select claim_token::text from public.claim_media_cleanup(100) where object_key='synthetic-ledger-key'),true);
select is(public.finish_media_cleanup('synthetic-ledger-key','86000000-0000-4000-8000-000000000003',true),false,'wrong cleanup token rejected');
select is(public.finish_media_cleanup('synthetic-ledger-key',current_setting('test.cleanup_token')::uuid,true),true,'claimed cleanup records a successful attempt');
select set_config('test.prefix_token',(select claim_token::text from public.claim_retired_article_prefixes(100) where article_id='86000000-0000-4000-8000-000000000001'),true);
select is(public.register_retired_media_keys('86000000-0000-4000-8000-000000000001',array['86000000-0000-4000-8000-000000000004'::uuid],current_setting('test.prefix_token')::uuid),true,'discovered canonical key is registered');
select is(public.finish_retired_article_scan_v2('86000000-0000-4000-8000-000000000001',current_setting('test.prefix_token')::uuid,1,true,true),true,'prefix scan releases claim');
reset role;
select is((select count(*)::int from private.media_cleanup_ledger where article_id='86000000-0000-4000-8000-000000000001'),2,'successful attempts remain in ledger for future late uploads');
select is((select scan_offset from private.retired_article_ids where article_id='86000000-0000-4000-8000-000000000001'),0,'prefix scan wraps after last page');
-- More work than one batch remains visible as stale, and expired claims can be recovered.
insert into private.media_key_registry(object_key,asset_id,article_id,retired)
 select 'bulk-key-'||n,gen_random_uuid(),'86000000-0000-4000-8000-000000000001',true from generate_series(1,35) n;
insert into private.media_cleanup_ledger(object_key,asset_id,article_id,created_at)
 select object_key,asset_id,article_id,now()-interval '8 days' from private.media_key_registry where object_key like 'bulk-key-%';
set local role service_role;
select is((select count(*)::int from public.claim_media_cleanup(30)),30,'cleanup claims at most one bounded batch');
select cmp_ok((public.get_media_cleanup_backlog()->>'staleKeys')::int,'>=',5,'older work beyond one batch remains visible');
reset role;
update private.media_cleanup_ledger set claim_until=now()-interval '1 minute',last_attempt_at=null where object_key='bulk-key-1';
set local role service_role;
select is((select count(*)::int from public.claim_media_cleanup(1) where object_key='bulk-key-1'),1,'expired claims can be recovered');
reset role;
set local role service_role;
select set_config('test.prefix_token',(select claim_token::text from public.claim_retired_article_prefixes(100) where article_id='86000000-0000-4000-8000-000000000001'),true);
select is(public.finish_retired_article_scan_v2('86000000-0000-4000-8000-000000000001',current_setting('test.prefix_token')::uuid,100,true,false),true,'mixed page is recorded');
reset role;
select is((select scan_offset from private.retired_article_ids where article_id='86000000-0000-4000-8000-000000000001'),100,'scan advances beyond a quarantined entry');
select is((select last_succeeded from private.retired_article_ids where article_id='86000000-0000-4000-8000-000000000001'),false,'scan error remains visible');
set local role service_role;
select set_config('test.prefix_token',(select claim_token::text from public.claim_retired_article_prefixes(100) where article_id='86000000-0000-4000-8000-000000000001'),true);
select is(public.finish_retired_article_scan_v2('86000000-0000-4000-8000-000000000001',current_setting('test.prefix_token')::uuid,1,true,true),true,'later page finishes');
reset role;
select is((select scan_offset from private.retired_article_ids where article_id='86000000-0000-4000-8000-000000000001'),0,'completed scan wraps to discover late earlier keys');
select is((select last_succeeded from private.retired_article_ids where article_id='86000000-0000-4000-8000-000000000001'),false,'cycle with an error stays unhealthy');
set local role service_role;
select set_config('test.prefix_token',(select claim_token::text from public.claim_retired_article_prefixes(100) where article_id='86000000-0000-4000-8000-000000000001'),true);
select is(public.finish_retired_article_scan_v2('86000000-0000-4000-8000-000000000001',current_setting('test.prefix_token')::uuid,1,true,true),true,'clean follow-up cycle finishes');
reset role;
select is((select last_succeeded from private.retired_article_ids where article_id='86000000-0000-4000-8000-000000000001'),true,'clean full cycle clears previous error');
select * from finish();
rollback;
